//! Substring temporary/output admission never mutates the queried node.
use super::*;
#[test]
fn character_substring_no_native_slot_copy_output_refusal_and_recovery_preserve_real_units(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);let nodes=doc.nodes.len();page.state.node_limit=nodes;assert_eq!(page.console_eval(&mut doc,&mut forms,"var owner=new Document(),source=owner.createTextNode('A\\ud83d\\ude00B\\ud800');").errors,0);let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};assert!(node_index(source).is_none());page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let args=[Value::Number(1.0),Value::Number(2.0)];let before=(b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len());let copies=b.state.copy_work;
 for allowance in [0,4]{b.state.copy_work=allowance;assert!(b.native_substring_data(source,&args).is_err());assert_eq!((b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len()),before);}
 b.state.copy_work=0;assert!(matches!(b.native_substring_data(source,&[Value::Number(5.0),Value::Number(99.0)]).unwrap(),Value::String(s) if s.is_empty()));b.state.copy_work=copies;let limit=b.state.limits.host.string_bytes;b.state.limits.host.string_bytes=1;assert!(b.native_substring_data(source,&args).is_err());assert_eq!((b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len()),before);b.state.limits.host.string_bytes=limit;
 assert!(matches!(b.native_substring_data(source,&args).unwrap(),Value::String(s) if s=="😀"));assert!(matches!(b.native_substring_data(source,&[Value::Number(4.0),Value::Number(1.0)]).unwrap(),Value::StringUnits(units) if units==vec![0xd800]));assert_eq!(b.character_data_source(source).unwrap().code_units().collect::<Vec<_>>(),vec![0x41,0xd83d,0xde00,0x42,0xd800]);assert_eq!(b.doc.nodes.len(),nodes);assert_eq!((b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len()),before);
}
